38	  const handlers = useMemo<Record<string, MiaActionHandler>>(() => ({
39	    // ── Filter encomendas ──
40	    encomendas_filter: {
41	      id: 'encomendas_filter',
42	      description: 'Filtrar encomendas por tipo, status e loja',
43	      execute: (data) => {
44	        if (!data) return;
45	        if (data.tipo !== undefined) {
46	          const tipos = Array.isArray(data.tipo) ? data.tipo : [data.tipo];
47	          setTipoFilter(tipos);
48	        }
49	        if (data.status !== undefined) {
50	          const statuses = Array.isArray(data.status) ? data.status : [data.status];
51	          setStatusFilter(statuses);
52	        }
53	        if (data.loja !== undefined) setLojaFilter(data.loja);
54	      },
55	    },
56	
57	    // ── Switch view mode ──
58	    encomendas_switch_view: {
59	      id: 'encomendas_switch_view',
60	      description: 'Trocar modo de visualizacao das encomendas (kanban/lista)',
