65	
66	    // ── Select tab ──
67	    encomendas_select_tab: {
68	      id: 'encomendas_select_tab',
69	      description: 'Selecionar aba de encomendas (pedidos/analytics)',
70	      execute: (data) => {
71	        if (data?.tab) setActiveTab(data.tab);
72	      },
73	    },
74	
75	    // ── Create encomenda ──
76	    encomendas_create: {
77	      id: 'encomendas_create',
78	      description: 'Abrir dialog de nova encomenda e preencher dados',
79	      execute: async (data) => {
80	        setIsCreateOpen(true);
81	        if (!data) return;
82	        // Wait for dialog to render
83	        await new Promise(r => setTimeout(r, 300));
84	        setForm((prev: any) => {
85	          const next = { ...prev };
86	          if (data.tipo !== undefined) next.tipo = data.tipo;
87	          if (data.loja_id !== undefined) next.loja_id = String(data.loja_id);
88	          if (data.cliente_nome !== undefined) next.cliente_nome = data.cliente_nome;
89	          if (data.data_entrega !== undefined) next.data_entrega = data.data_entrega;
90	          if (data.hora_entrega !== undefined) next.hora_entrega = data.hora_entrega;
91	          if (data.pedido_descricao !== undefined) next.pedido_descricao = data.pedido_descricao;
92	          if (data.preco !== undefined) next.preco = String(data.preco);
93	          return next;
94	        });
95	      },
96	    },
97	
98	    // ── Open order detail ──
99	    encomendas_open_detail: {
100	      id: 'encomendas_open_detail',
101	      description: 'Abrir detalhes de uma encomenda especifica',
102	      execute: (data) => {
103	        if (!data) return;
104	        let found = null;
105	        if (data.order_id) {
106	          found = orders.find((o: any) => o.id === data.order_id || String(o.id) === String(data.order_id));
107	        }
108	        if (!found && data.client_name) {
109	          found = orders.find((o: any) =>
110	            o.cliente_nome?.toLowerCase().includes(data.client_name.toLowerCase())
111	          );
112	        }
113	        if (found) setIsDetailsOpen(found);
114	      },
115	    },
116	
117	    // ── Show finalized orders ──
118	    encomendas_show_finalized: {
119	      id: 'encomendas_show_finalized',
120	      description: 'Exibir encomendas finalizadas',
121	      execute: () => {
122	        setIsFinalizedOpen(true);
123	      },
124	    },
125	
126	    // ── Print day orders ──
127	    encomendas_print_day: {
128	      id: 'encomendas_print_day',
129	      description: 'Imprimir pedidos de um dia especifico',
130	      execute: (data) => {
131	        if (!data?.date) return;
132	        const label = data.label || data.date;
133	        printDayOrders(data.date, label);
134	      },
135	    },
136	
137	    // ── Refresh orders ──
138	    encomendas_refresh: {
139	      id: 'encomendas_refresh',
140	      description: 'Atualizar lista de encomendas',
141	      execute: async () => {
142	        await fetchOrders();
143	      },
144	    },
145	
146	    // ── Clear filters ──
147	    clear_filters: {
148	      id: 'clear_filters',
149	      description: 'Limpar filtros das encomendas',
150	      execute: () => {
151	        setTipoFilter(['delivery', 'retirada']);
152	        setStatusFilter(['aberto']);
153	        setLojaFilter('');
154	      },
155	    },
156	  }), [
157	    setActiveTab,
158	    setViewMode,
159	    setTipoFilter,
160	    setStatusFilter,
161	    setLojaFilter,
162	    setIsCreateOpen,
163	    setIsDetailsOpen,
164	    setIsFinalizedOpen,
165	    setForm,
166	    handleCreate,
167	    printDayOrders,
168	    fetchOrders,
169	    orders,
170	  ]);
171	
172	  useMiaActions('/encomendas', handlers);
173	}
